# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def make_student(last, first):
    return Student(student_id=last, last_name=last, first_name=first, section="A")


class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Halloway", "Juno"),
            make_student("Quillon", "Ada"),
            make_student("Dunmere", "Piet"),
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Quillon, Ada"]
        )

    def test_single_wide_row(self):
        self.assertEqual(len(seating_rows(self.students, 10)), 1)

    def test_first_name_breaks_ties(self):
        pair = [make_student("Thistle", "Bram"), make_student("Thistle", "Abe")]
        self.assertEqual(
            seating_rows(pair, 2), ["Row 1: Thistle, Abe | Thistle, Bram"]
        )

    def test_zero_seats(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)

    def test_no_students(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
